// Dashboard.jsx

import React, { useState, useEffect } from "react";
import { apiRequest, logout, setNavigateInstance } from "../services/auth";
import { useNavigate } from "react-router-dom";

const Dashboard = () => {
  const [activeSection, setActiveSection] = useState("accueil");
  const [selectedEntreprise, setSelectedEntreprise] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [showAddEntrepriseModal, setShowAddEntrepriseModal] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [addEntrepriseData, setAddEntrepriseData] = useState({
    nom: "",
    siret: "",
    telephone: "",
    email: "",
    nomRepresentant: "",
    prenomRepresentant: "",
    domainesActivite: [],
    secteurActivite: "",
  });
  const [profileData, setProfileData] = useState({
    id: null, // Ajout de l'ID pour la mise à jour de l'entreprise
    nom: "Logo service",
    siret: "12345678901234",
    adresse: "Ouagadougou 01 BP 824",
    email: "contact@techbat.fr",
    telephone: "0123456789",
    nomRepresentant: "Rayaissse ",
    prenomRepresentant: "Jude",
    secteurActivite: "", // Initialiser à vide pour récupérer de l'API
    domainesActivite: [], // Initialiser à vide pour récupérer de l'API
  });

  const [apiDomainesActivite, setApiDomainesActivite] = useState([]);
  const [apiSecteursActivite, setApiSecteursActivite] = useState([]);
  const [loadingDomaines, setLoadingDomaines] = useState(false);
  const [errorDomaines, setErrorDomaines] = useState(null);
  const [loadingSecteurs, setLoadingSecteurs] = useState(false);
  const [errorSecteurs, setErrorSecteurs] = useState(null);
  const [otherSecteur, setOtherSecteur] = useState("");
  const [otherDomaine, setOtherDomaine] = useState("");

  const navigate = useNavigate();

  useEffect(() => {
    setNavigateInstance(navigate);
  }, [navigate]);

  useEffect(() => {
    const fetchDomainesAndSecteurs = async () => {
      setLoadingDomaines(true);
      setErrorDomaines(null);
      setLoadingSecteurs(true);
      setErrorSecteurs(null);
      try {
        const [domainesResponse, secteursResponse, activeEntrepriseResponse] =
          await Promise.all([
            apiRequest("http://127.0.0.1:8000/api/entreprise/domaines/"),
            apiRequest("http://127.0.0.1:8000/api/entreprise/secteurs/"),
            apiRequest(
              "http://127.0.0.1:8000/api/entreprise/entreprises/active/"
            ),
          ]);

        if (!domainesResponse.ok)
          throw new Error(`Erreur HTTP domaines: ${domainesResponse.status}`);
        if (!secteursResponse.ok)
          throw new Error(`Erreur HTTP secteurs: ${secteursResponse.status}`);
        if (!activeEntrepriseResponse.ok)
          throw new Error(
            `Erreur HTTP entreprise active: ${activeEntrepriseResponse.status}`
          );

        const domainesData = await domainesResponse.json();
        const secteursData = await secteursResponse.json();
        const activeEntrepriseData = await activeEntrepriseResponse.json();

        setApiDomainesActivite(domainesData);
        setApiSecteursActivite(secteursData);

        // Mise à jour du profileData avec les informations de l'entreprise active
        if (activeEntrepriseData) {
          setProfileData((prevData) => ({
            ...prevData,
            nom: activeEntrepriseData.nom || prevData.nom,
            siret: activeEntrepriseData.siret || prevData.siret,
            adresse: activeEntrepriseData.adresse || prevData.adresse,
            email: activeEntrepriseData.email || prevData.email,
            telephone: activeEntrepriseData.telephone || prevData.telephone,
            nomRepresentant:
              activeEntrepriseData.nomRepresentant || prevData.nomRepresentant,
            prenomRepresentant:
              activeEntrepriseData.prenomRepresentant ||
              prevData.prenomRepresentant,
            secteurActivite: activeEntrepriseData.secteurActivite
              ? activeEntrepriseData.secteurActivite.nom
              : "",
            domainesActivite:
              activeEntrepriseData.domaines.map((d) => d.libelle) || [],
            id: activeEntrepriseData.id, // Stocker l'ID de l'entreprise pour les mises à jour
          }));
        }
      } catch (error) {
        console.error("Erreur lors de la récupération des données :", error);
        setErrorDomaines(error);
        setErrorSecteurs(error);
      } finally {
        setLoadingDomaines(false);
        setLoadingSecteurs(false);
      }
    };

    fetchDomainesAndSecteurs();
  }, []);

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  const handleAddEntrepriseChange = (e) => {
    const { name, value } = e.target;
    setAddEntrepriseData({ ...addEntrepriseData, [name]: value });
  };

  const handleAddEntrepriseSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await apiRequest(
        "http://127.0.0.1:8000/api/entreprise/entreprises/",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(addEntrepriseData),
        }
      );
      if (response.ok) {
        alert("Entreprise ajoutée avec succès !");
        setShowAddEntrepriseModal(false);
        // Vous pourriez vouloir rafraîchir la liste des entreprises ou le profil après l'ajout
      } else {
        const errorData = await response.json();
        alert(
          `Échec de l'ajout de l'entreprise : ${JSON.stringify(errorData)}`
        );
      }
    } catch (error) {
      console.error("Erreur lors de l'ajout de l'entreprise :", error);
      alert("Une erreur est survenue lors de l'ajout de l'entreprise.");
    }
  };

  const handleProfileChange = (e) => {
    const { name, value } = e.target;
    setProfileData({ ...profileData, [name]: value });
  };

  const handleDomaineChange = (domaine) => {
    setProfileData((prevData) => {
      const newDomaines = prevData.domainesActivite.includes(domaine)
        ? prevData.domainesActivite.filter((d) => d !== domaine)
        : [...prevData.domainesActivite, domaine];
      return { ...prevData, domainesActivite: newDomaines };
    });
  };

  const handleUpdateSecteur = async () => {
    if (!profileData.id) {
      alert(
        "ID de l'entreprise non disponible. Impossible de mettre à jour le secteur."
      );
      return;
    }

    try {
      let selectedSecteurId = null;
      if (otherSecteur) {
        // Ajouter le nouveau secteur s'il est renseigné
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/entreprise/secteurs/",
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              nom: otherSecteur,
              description: otherSecteur,
            }),
          }
        );
        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(
            `Erreur lors de l'ajout du secteur: ${JSON.stringify(errorData)}`
          );
        }
        const newSecteur = await response.json();
        selectedSecteurId = newSecteur.id;
        // Rafraîchir la liste des secteurs après l'ajout
        const secteursResponse = await apiRequest(
          "http://127.0.0.1:8000/api/entreprise/secteurs/"
        );
        if (secteursResponse.ok) {
          const data = await secteursResponse.json();
          setApiSecteursActivite(data);
        }
      } else if (profileData.secteurActivite) {
        // Récupérer l'ID du secteur sélectionné s'il existe
        const foundSecteur = apiSecteursActivite.find(
          (s) => s.nom === profileData.secteurActivite
        );
        if (foundSecteur) {
          selectedSecteurId = foundSecteur.id;
        } else {
          alert("Secteur d'activité sélectionné introuvable.");
          return;
        }
      }

      // Mettre à jour l'entreprise avec le secteur sélectionné
      const updateResponse = await apiRequest(
        `http://127.0.0.1:8000/api/entreprise/entreprises/${profileData.id}/`,
        {
          method: "PATCH", // Utiliser PATCH pour la mise à jour partielle
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ secteurActivite: selectedSecteurId }),
        }
      );

      if (!updateResponse.ok) {
        const errorData = await updateResponse.json();
        throw new Error(
          `Erreur lors de la mise à jour du secteur de l'entreprise: ${JSON.stringify(
            errorData
          )}`
        );
      }

      alert("Secteur d'activité mis à jour avec succès !");
      setOtherSecteur(""); // Réinitialiser le champ 'Autre secteur'
      // Re-fetch les données de l'entreprise active pour s'assurer que l'état est à jour
      const activeEntrepriseResponse = await apiRequest(
        "http://127.0.0.1:8000/api/entreprise/entreprises/active/"
      );
      if (activeEntrepriseResponse.ok) {
        const activeEntrepriseData = await activeEntrepriseResponse.json();
        setProfileData((prevData) => ({
          ...prevData,
          secteurActivite: activeEntrepriseData.secteurActivite
            ? activeEntrepriseData.secteurActivite.nom
            : "",
        }));
      }
    } catch (error) {
      console.error("Erreur lors de la mise à jour du secteur :", error);
      alert(`Échec de la mise à jour du secteur : ${error.message}`);
    }
  };

  const handleUpdateDomaines = async () => {
    if (!profileData.id) {
      alert(
        "ID de l'entreprise non disponible. Impossible de mettre à jour les domaines."
      );
      return;
    }

    try {
      let currentDomainesIds = [];

      // Récupérer les IDs des domaines déjà sélectionnés
      currentDomainesIds = apiDomainesActivite
        .filter((domaine) =>
          profileData.domainesActivite.includes(domaine.libelle)
        )
        .map((domaine) => domaine.id);

      if (otherDomaine) {
        // Ajouter le nouveau domaine s'il est renseigné
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/entreprise/domaines/",
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              libelle: otherDomaine,
              description: otherDomaine,
            }),
          }
        );
        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(
            `Erreur lors de l'ajout du domaine: ${JSON.stringify(errorData)}`
          );
        }
        const newDomaine = await response.json();
        currentDomainesIds.push(newDomaine.id); // Ajouter le nouvel ID aux domaines de l'entreprise
        // Rafraîchir la liste des domaines après l'ajout
        const domainesResponse = await apiRequest(
          "http://127.0.0.1:8000/api/entreprise/domaines/"
        );
        if (domainesResponse.ok) {
          const data = await domainesResponse.json();
          setApiDomainesActivite(data);
        }
      }

      // Mettre à jour l'entreprise avec la liste des IDs de domaines
      const updateResponse = await apiRequest(
        `http://127.0.0.1:8000/api/entreprise/entreprises/${profileData.id}/`,
        {
          method: "PATCH", // Utiliser PATCH pour la mise à jour partielle
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ domaines: currentDomainesIds }),
        }
      );

      if (!updateResponse.ok) {
        const errorData = await updateResponse.json();
        throw new Error(
          `Erreur lors de la mise à jour des domaines de l'entreprise: ${JSON.stringify(
            errorData
          )}`
        );
      }

      alert("Domaines d'activité mis à jour avec succès !");
      setOtherDomaine(""); // Réinitialiser le champ 'Autre domaine'
      // Re-fetch les données de l'entreprise active pour s'assurer que l'état est à jour
      const activeEntrepriseResponse = await apiRequest(
        "http://127.0.0.1:8000/api/entreprise/entreprises/active/"
      );
      if (activeEntrepriseResponse.ok) {
        const activeEntrepriseData = await activeEntrepriseResponse.json();
        setProfileData((prevData) => ({
          ...prevData,
          domainesActivite:
            activeEntrepriseData.domaines.map((d) => d.libelle) || [],
        }));
      }
    } catch (error) {
      console.error("Erreur lors de la mise à jour des domaines :", error);
      alert(`Échec de la mise à jour des domaines : ${error.message}`);
    }
  };

  const renderMobileHeader = () => (
    <div className="mobile-header d-flex justify-content-between align-items-center p-3 d-lg-none">
      <button
        className="btn btn-primary"
        onClick={() => setSidebarOpen(!sidebarOpen)}
      >
        ☰
      </button>
      <h3 className="m-0">Tableau de bord</h3>
      <button className="btn btn-danger" onClick={handleLogout}>
        Déconnexion
      </button>
    </div>
  );

  const renderSidebar = () => (
    <div
      className={`sidebar ${sidebarOpen ? "open" : ""} d-flex flex-column p-3`}
    >
      <div className="sidebar-header d-flex justify-content-between align-items-center mb-4">
        <h2 className="text-white m-0">Tableau de bord</h2>
        <button
          className="btn btn-close btn-close-white d-lg-none"
          onClick={() => setSidebarOpen(false)}
        ></button>
      </div>
      <ul className="nav flex-column mb-auto">
        <li className="nav-item">
          <a
            href="#!"
            className={`nav-link text-white ${
              activeSection === "accueil" ? "active" : ""
            }`}
            onClick={() => {
              setActiveSection("accueil");
              setSidebarOpen(false);
            }}
          >
            Accueil
          </a>
        </li>
        <li className="nav-item">
          <a
            href="#!"
            className={`nav-link text-white ${
              activeSection === "veille" ? "active" : ""
            }`}
            onClick={() => {
              setActiveSection("veille");
              setSidebarOpen(false);
            }}
          >
            Veille Règlementaire
          </a>
        </li>
        <li className="nav-item">
          <a
            href="#!"
            className={`nav-link text-white ${
              activeSection === "alertes" ? "active" : ""
            }`}
            onClick={() => {
              setActiveSection("alertes");
              setSidebarOpen(false);
            }}
          >
            Mes alertes
          </a>
        </li>
        <li className="nav-item">
          <a
            href="#!"
            className={`nav-link text-white ${
              activeSection === "profil" ? "active" : ""
            }`}
            onClick={() => {
              setActiveSection("profil");
              setSidebarOpen(false);
            }}
          >
            Profil
          </a>
        </li>
      </ul>
      <div className="sidebar-footer mt-auto">
        <button className="btn btn-danger w-100" onClick={handleLogout}>
          Déconnexion
        </button>
      </div>
    </div>
  );

  const renderAccueil = () => (
    <div className="dashboard-content p-4">
      <h1 className="mb-4">Bienvenue sur votre Tableau de Bord !</h1>
      <div className="row">
        <div className="col-md-6 mb-4">
          <div className="card">
            <div className="card-body">
              <h5 className="card-title">Résumé de la Veille</h5>
              <p className="card-text">
                Consultez les dernières mises à jour réglementaires.
              </p>
              <button
                className="btn btn-cta"
                onClick={() => setActiveSection("veille")}
              >
                Accéder à la Veille
              </button>
            </div>
          </div>
        </div>
        <div className="col-md-6 mb-4">
          <div className="card">
            <div className="card-body">
              <h5 className="card-title">Vos Alertes</h5>
              <p className="card-text">
                Gérez vos alertes personnalisées pour ne rien manquer.
              </p>
              <button
                className="btn btn-cta"
                onClick={() => setActiveSection("alertes")}
              >
                Gérer les Alertes
              </button>
            </div>
          </div>
        </div>
        <div className="col-md-6 mb-4">
          <div className="card">
            <div className="card-body">
              <h5 className="card-title">Votre Profil</h5>
              <p className="card-text">
                Mettez à jour les informations de votre entreprise.
              </p>
              <button
                className="btn btn-cta"
                onClick={() => setActiveSection("profil")}
              >
                Modifier le Profil
              </button>
            </div>
          </div>
        </div>
        <div className="col-md-6 mb-4">
          <div className="card">
            <div className="card-body">
              <h5 className="card-title">Ajouter une entreprise</h5>
              <p className="card-text">
                Enregistrez une nouvelle entreprise dans le système.
              </p>
              <button
                className="btn btn-cta"
                onClick={() => setShowAddEntrepriseModal(true)}
              >
                Ajouter une entreprise
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderVeille = () => {
    const documents = [
      {
        id: 1,
        title: "Nouvelle Réglementation sur l'Énergie Renouvelable",
        date: "2023-04-15",
        description:
          "Texte officiel concernant les nouvelles directives européennes sur la production d'énergie solaire et éolienne.",
        source: "https://example.com/energie_renouvelable.pdf",
      },
      {
        id: 2,
        title: "Mise à jour des Normes de Sécurité Industrielle",
        date: "2023-03-20",
        description:
          "Amendements aux normes de sécurité pour les usines de fabrication, incluant de nouvelles exigences pour la protection des travailleurs.",
        source: "https://example.com/securite_industrielle.pdf",
      },
      {
        id: 3,
        title: "Loi sur la Protection des Données Personnelles (RGPD)",
        date: "2023-02-10",
        description:
          "Consolidation des textes législatifs relatifs à la protection des données personnelles et à la vie privée.",
        source: "https://example.com/rgpd_consolide.pdf",
      },
    ];

    return (
      <div className="dashboard-content p-4">
        <h1 className="mb-4">Veille Règlementaire</h1>
        <div className="list-group">
          {documents.map((doc) => (
            <button
              key={doc.id}
              type="button"
              className="list-group-item list-group-item-action d-flex justify-content-between align-items-center"
              onClick={() => {
                setSelectedDocument(doc);
                setShowModal(true);
              }}
            >
              <div>
                <h5>{doc.title}</h5>
                <p className="mb-1">{doc.description}</p>
                <small>Publié le : {doc.date}</small>
              </div>
              <span className="badge bg-primary rounded-pill">Détails</span>
            </button>
          ))}
        </div>
      </div>
    );
  };

  const renderAlertes = () => (
    <div className="dashboard-content p-4">
      <h1 className="mb-4">Mes Alertes</h1>
      <p>Pas d'alertes configurées pour le moment.</p>
      {/* Ici, vous pouvez ajouter une interface pour configurer les alertes */}
    </div>
  );

  const renderProfil = () => (
    <div className="dashboard-content p-4">
      <h1 className="mb-4">Profil de l'Entreprise</h1>
      <form>
        <div className="mb-3">
          <label htmlFor="nom" className="form-label">
            Nom de l'entreprise
          </label>
          <input
            type="text"
            className="form-control"
            id="nom"
            name="nom"
            value={profileData.nom}
            onChange={handleProfileChange}
          />
        </div>
        <div className="mb-3">
          <label htmlFor="siret" className="form-label">
            Numéro SIRET
          </label>
          <input
            type="text"
            className="form-control"
            id="siret"
            name="siret"
            value={profileData.siret}
            onChange={handleProfileChange}
          />
        </div>
        <div className="mb-3">
          <label htmlFor="adresse" className="form-label">
            Adresse
          </label>
          <input
            type="text"
            className="form-control"
            id="adresse"
            name="adresse"
            value={profileData.adresse}
            onChange={handleProfileChange}
          />
        </div>
        <div className="mb-3">
          <label htmlFor="email" className="form-label">
            Email
          </label>
          <input
            type="email"
            className="form-control"
            id="email"
            name="email"
            value={profileData.email}
            onChange={handleProfileChange}
          />
        </div>
        <div className="mb-3">
          <label htmlFor="telephone" className="form-label">
            Téléphone
          </label>
          <input
            type="tel"
            className="form-control"
            id="telephone"
            name="telephone"
            value={profileData.telephone}
            onChange={handleProfileChange}
          />
        </div>
        <div className="mb-3">
          <label htmlFor="nomRepresentant" className="form-label">
            Nom du représentant
          </label>
          <input
            type="text"
            className="form-control"
            id="nomRepresentant"
            name="nomRepresentant"
            value={profileData.nomRepresentant}
            onChange={handleProfileChange}
          />
        </div>
        <div className="mb-3">
          <label htmlFor="prenomRepresentant" className="form-label">
            Prénom du représentant
          </label>
          <input
            type="text"
            className="form-control"
            id="prenomRepresentant"
            name="prenomRepresentant"
            value={profileData.prenomRepresentant}
            onChange={handleProfileChange}
          />
        </div>

        <div className="mb-3">
          <label htmlFor="secteurActivite" className="form-label">
            Secteur d'activité
          </label>
          {loadingSecteurs ? (
            <p>Chargement des secteurs...</p>
          ) : errorSecteurs ? (
            <p className="text-danger">Erreur: {errorSecteurs.message}</p>
          ) : (
            <>
              <select
                className="form-select"
                id="secteurActivite"
                name="secteurActivite"
                value={profileData.secteurActivite}
                onChange={handleProfileChange}
              >
                <option value="">Sélectionnez un secteur</option>
                {apiSecteursActivite.map((secteur) => (
                  <option key={secteur.id} value={secteur.nom}>
                    {secteur.nom}
                  </option>
                ))}
              </select>
              <small className="form-text text-muted">
                Votre secteur actuel est :{" "}
                {profileData.secteurActivite || "Non défini"}
              </small>
              <div className="mt-2">
                <input
                  type="text"
                  className="form-control"
                  placeholder="Ou précisez votre secteur d'activité..."
                  value={otherSecteur}
                  onChange={(e) => setOtherSecteur(e.target.value)}
                />
              </div>
              <button
                type="button"
                className="btn btn-cta mt-3"
                onClick={handleUpdateSecteur}
              >
                Mettre à jour le secteur
              </button>
            </>
          )}
        </div>

        <div className="mb-3">
          <label className="form-label">Domaines d'activité</label>
          {loadingDomaines ? (
            <p>Chargement des domaines...</p>
          ) : errorDomaines ? (
            <p className="text-danger">Erreur: {errorDomaines.message}</p>
          ) : (
            <>
              {apiDomainesActivite.map((domaine) => (
                <div className="form-check" key={domaine.id}>
                  <input
                    className="form-check-input"
                    type="checkbox"
                    id={`domaine-${domaine.id}`}
                    value={domaine.libelle}
                    checked={profileData.domainesActivite.includes(
                      domaine.libelle
                    )}
                    onChange={() => handleDomaineChange(domaine.libelle)}
                  />
                  <label
                    className="form-check-label"
                    htmlFor={`domaine-${domaine.id}`}
                  >
                    {domaine.libelle}
                  </label>
                </div>
              ))}
              <div className="mt-2">
                <input
                  type="text"
                  className="form-control"
                  placeholder="Ou précisez un autre domaine d'activité..."
                  value={otherDomaine}
                  onChange={(e) => setOtherDomaine(e.target.value)}
                />
              </div>
              <button
                type="button"
                className="btn btn-cta mt-3"
                onClick={handleUpdateDomaines}
              >
                Mettre à jour les domaines
              </button>
            </>
          )}
        </div>

        {/* <button type="submit" className="btn btn-primary">
          Mettre à jour le Profil
        </button> */}
      </form>
    </div>
  );

  const renderAddEntrepriseModal = () => (
    <div
      className={`modal fade ${showAddEntrepriseModal ? "show d-block" : ""}`}
      tabIndex="-1"
      aria-labelledby="addEntrepriseModalLabel"
      aria-hidden={!showAddEntrepriseModal}
      style={{ display: showAddEntrepriseModal ? "block" : "none" }}
    >
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title" id="addEntrepriseModalLabel">
              Ajouter une nouvelle entreprise
            </h5>
            <button
              type="button"
              className="btn-close"
              aria-label="Close"
              onClick={() => setShowAddEntrepriseModal(false)}
            ></button>
          </div>
          <div className="modal-body">
            <form onSubmit={handleAddEntrepriseSubmit}>
              <div className="mb-3">
                <label htmlFor="addNom" className="form-label">
                  Nom de l'entreprise
                </label>
                <input
                  type="text"
                  className="form-control"
                  id="addNom"
                  name="nom"
                  value={addEntrepriseData.nom}
                  onChange={handleAddEntrepriseChange}
                  required
                />
              </div>
              <div className="mb-3">
                <label htmlFor="addSiret" className="form-label">
                  Numéro SIRET
                </label>
                <input
                  type="text"
                  className="form-control"
                  id="addSiret"
                  name="siret"
                  value={addEntrepriseData.siret}
                  onChange={handleAddEntrepriseChange}
                  required
                />
              </div>
              <div className="mb-3">
                <label htmlFor="addTelephone" className="form-label">
                  Téléphone
                </label>
                <input
                  type="tel"
                  className="form-control"
                  id="addTelephone"
                  name="telephone"
                  value={addEntrepriseData.telephone}
                  onChange={handleAddEntrepriseChange}
                />
              </div>
              <div className="mb-3">
                <label htmlFor="addEmail" className="form-label">
                  Email
                </label>
                <input
                  type="email"
                  className="form-control"
                  id="addEmail"
                  name="email"
                  value={addEntrepriseData.email}
                  onChange={handleAddEntrepriseChange}
                  required
                />
              </div>
              <div className="mb-3">
                <label htmlFor="addNomRepresentant" className="form-label">
                  Nom du représentant
                </label>
                <input
                  type="text"
                  className="form-control"
                  id="addNomRepresentant"
                  name="nomRepresentant"
                  value={addEntrepriseData.nomRepresentant}
                  onChange={handleAddEntrepriseChange}
                />
              </div>
              <div className="mb-3">
                <label htmlFor="addPrenomRepresentant" className="form-label">
                  Prénom du représentant
                </label>
                <input
                  type="text"
                  className="form-control"
                  id="addPrenomRepresentant"
                  name="prenomRepresentant"
                  value={addEntrepriseData.prenomRepresentant}
                  onChange={handleAddEntrepriseChange}
                />
              </div>
              {/* Vous pouvez ajouter des champs pour secteur et domaines si vous les gérez ici aussi */}
              <button type="submit" className="btn btn-cta">
                Ajouter
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );

  const renderModal = () => (
    <div
      className={`modal fade ${showModal ? "show d-block" : ""}`}
      tabIndex="-1"
      aria-labelledby="documentModalLabel"
      aria-hidden={!showModal}
      style={{ display: showModal ? "block" : "none" }}
    >
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title" id="documentModalLabel">
              {selectedDocument
                ? selectedDocument.title
                : "Détails du document"}
            </h5>
            <button
              type="button"
              className="btn-close"
              aria-label="Close"
              onClick={() => setShowModal(false)}
            ></button>
          </div>
          <div className="modal-body">
            {selectedDocument ? (
              <>
                <p>
                  <strong>Date:</strong> {selectedDocument.date}
                </p>
                <p>
                  <strong>Description:</strong> {selectedDocument.description}
                </p>
              </>
            ) : (
              <p>Aucun document sélectionné.</p>
            )}
          </div>
          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowModal(false)}
            >
              Fermer
            </button>
            {/* Modification ici pour le bouton Télécharger */}
            {selectedDocument && selectedDocument.source ? (
              <a
                href={selectedDocument.source}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-cta"
              >
                Télécharger
              </a>
            ) : (
              <button type="button" className="btn btn-secondary" disabled>
                Télécharger (lien non disponible)
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeSection) {
      case "accueil":
        return renderAccueil();
      case "veille":
        return renderVeille();
      case "alertes":
        return renderAlertes();
      case "profil":
        return renderProfil();
      default:
        return renderAccueil();
    }
  };

  return (
    <>
      <div className="dashboard-container">
        {renderMobileHeader()}
        {renderSidebar()}
        <div className="main-wrapper">{renderContent()}</div>
        {showModal && renderModal()}
        {showAddEntrepriseModal && renderAddEntrepriseModal()}
      </div>
    </>
  );
};

export default Dashboard;
